using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace CircuitoStudio {
public static class DiagramEditing {
static void Member(Project p,Board b){if(b==null||!p.Boards.Contains(b))throw new InvalidDataException("Quadro fora do projeto.");}
public static Circuit Connect(Project p,Board origin,Board target){p.Validate();Member(p,origin);Member(p,target);if(origin==target)throw new InvalidDataException("Um quadro não pode alimentar a si mesmo.");if(Math.Abs(origin.Voltage-target.Voltage)>.001)throw new InvalidDataException("Conexão exige a mesma tensão entre fases; transformação não é modelada.");var c=ProjectEditing.AddCircuit(p,origin);c.Name="Alimentação de "+target.Name;c.Kind="Alimentador";c.PowerKw=0;c.Phases=PhaseMode.Trifasico;c.PhaseLabel="ABC";c.Voltage=origin.Voltage;c.ChildBoardId=target.Id;try{p.Validate();Engineering.Analyze(p);return c;}catch{origin.Circuits.Remove(c);throw;}}
public static void Reconnect(Project p,Board origin,Circuit feeder,Board target){p.Validate();Member(p,origin);Member(p,target);if(feeder==null||!origin.Circuits.Contains(feeder)||feeder.ChildBoardId=="")throw new InvalidDataException("Selecione um alimentador existente; carga terminal não é convertida silenciosamente.");string old=feeder.ChildBoardId;feeder.ChildBoardId=target.Id;try{p.Validate();Engineering.Analyze(p);}catch{feeder.ChildBoardId=old;throw;}}
public static void Disconnect(Project p,Board origin,Circuit feeder){p.Validate();Member(p,origin);if(feeder==null||!origin.Circuits.Contains(feeder)||feeder.ChildBoardId=="")throw new InvalidDataException("Selecione um alimentador existente.");int index=origin.Circuits.IndexOf(feeder);origin.Circuits.RemoveAt(index);try{p.Validate();Engineering.Analyze(p);}catch{origin.Circuits.Insert(index,feeder);throw;}}
public static void Move(Project p,Board origin,Circuit c,double x,double y){p.Validate();Member(p,origin);if(c==null||!origin.Circuits.Contains(c))throw new InvalidDataException("Símbolo fora do quadro.");Project.Range(x,45,4000,"posição horizontal");Project.Range(y,115,4000,"posição vertical");c.DiagramX=x;c.DiagramY=y;}
}
public sealed class DiagramConnectionsForm:Form {
Project project;Board origin;Circuit selected;ComboBox targets=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=420};TextBox memory=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill};NumericUpDown x=new NumericUpDown{Minimum=45,Maximum=4000,Width=80},y=new NumericUpDown{Minimum=115,Maximum=4000,Width=80};public bool Changed{get;private set;}
sealed class Item{public Board Board;public override string ToString(){return Board.Id+" — "+Board.Name+" / "+Board.Voltage+" V";}}
public DiagramConnectionsForm(Project p,Board b,Circuit c){project=p;origin=b;selected=c;Text="Conexões do unifilar — "+b.Name;Size=new Size(920,590);MinimumSize=new Size(800,500);Font=new Font("Segoe UI",10);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=120,Padding=new Padding(8)};bar.Controls.Add(new Label{Text="Quadro de destino",AutoSize=true});bar.Controls.Add(targets);foreach(var target in p.Boards)targets.Items.Add(new Item{Board=target});if(targets.Items.Count>0)targets.SelectedIndex=Math.Max(0,p.Boards.FindIndex(t=>t.Id==(c==null?"":c.ChildBoardId)));Button(bar,"Criar alimentador",()=>{var f=DiagramEditing.Connect(p,b,Target());selected=f;Changed=true;RefreshState();});Button(bar,"Reconectar selecionado",()=>{DiagramEditing.Reconnect(p,b,selected,Target());Changed=true;RefreshState();});Button(bar,"Desconectar selecionado",()=>{DiagramEditing.Disconnect(p,b,selected);selected=null;Changed=true;RefreshState();});bar.SetFlowBreak(bar.Controls[bar.Controls.Count-1],true);bar.Controls.Add(new Label{Text="Posição X/Y do símbolo",AutoSize=true});bar.Controls.Add(x);bar.Controls.Add(y);Button(bar,"Mover símbolo",()=>{DiagramEditing.Move(p,b,selected,(double)x.Value,(double)y.Value);Changed=true;RefreshState();});Controls.Add(memory);Controls.Add(bar);RefreshState();}
Board Target(){var item=targets.SelectedItem as Item;if(item==null)throw new InvalidDataException("Selecione o destino.");return item.Board;}
void Button(Control bar,string label,Action action){var button=new Button{Text=label,AutoSize=true,Height=31};button.Click+=(s,e)=>{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Conexão inválida");}};bar.Controls.Add(button);}
void RefreshState(){var s=Engineering.Analyze(project);memory.Text="Origem: "+origin.Id+" / "+origin.Name+"\r\nSelecionado: "+(selected==null?"nenhum":selected.Id+" / "+selected.Name)+"\r\n\r\nCriar adiciona um alimentador próprio, sem converter ou perder uma carga terminal.\r\nReconectar mantém cabo, proteção, demanda e posição; o quadro antigo permanece como raiz.\r\nDesconectar remove o alimentador, preservando o quadro e seus circuitos como raiz independente.\r\nNão converte potência de alimentador em carga fantasma. Rede radial, sem transformação entre quadros.\r\nAlterações inválidas são revertidas; os estudos são recalculados em cada operação.\r\n\r\n"+String.Join("\r\n",origin.Circuits.Select(c=>c.Id+" → "+(c.ChildBoardId==""?"carga terminal":c.ChildBoardId)+" / "+s.For(c).DemandKw.ToString("N3")+" kW / "+s.For(c).CurrentA.ToString("N3")+" A"))+"\r\n\r\nTotal da rede: "+s.TotalKw.ToString("N3")+" kW.";memory.Select(0,0);targets.Focus();if(selected!=null){x.Value=(decimal)Math.Max(45,selected.DiagramX);y.Value=(decimal)Math.Max(115,selected.DiagramY);}}
}
partial class Studio {void EditDiagramConnections(){if(board==null)throw new InvalidDataException("Selecione um quadro.");using(var form=new DiagramConnectionsForm(project,board,circuit)){form.ShowDialog(this);if(form.Changed){Change();properties.SelectedObject=circuit??(object)board;}}}}
}
